#!/usr/bin/env node
/*
 * Generates src/buildInfo.ts, which the bridge reports via /health.
 *
 * Why this exists: package.json, file mtimes and the extension directory all
 * describe what is *on disk*. After installing a vsix the extension host keeps
 * running the previously loaded code until the window is reloaded, so none of
 * those can tell you which build is actually executing. A constant compiled
 * into the code can.
 *
 * The generated file is gitignored -- it is build output, not source.
 */
const fs = require('fs');
const path = require('path');
const { execFileSync } = require('child_process');

const root = path.join(__dirname, '..');

/** Runs a git command, or returns null when git/the repo is unavailable. */
function git(args) {
  try {
    return execFileSync('git', args, {
      cwd: root,
      encoding: 'utf8',
      stdio: ['ignore', 'pipe', 'ignore'],
    }).trim();
  } catch {
    return null;
  }
}

const version = JSON.parse(fs.readFileSync(path.join(root, 'package.json'), 'utf8')).version;
const commit = git(['rev-parse', '--short', 'HEAD']);
const status = git(['status', '--porcelain']);
const buildTime = new Date().toISOString();

// When git is unavailable commit is reported as 'unknown'; treat dirty as false
// in that case -- consumers should read 'unknown' as "no provenance", not "clean".
const contents = `// AUTO-GENERATED by scripts/gen-build-info.js -- do not edit, do not commit.
export const BUILD_VERSION = '${version}';
export const BUILD_TIME = '${buildTime}';
export const BUILD_COMMIT = '${commit ?? 'unknown'}';
export const BUILD_DIRTY = ${status === null ? false : status.length > 0};
`;

fs.writeFileSync(path.join(root, 'src', 'buildInfo.ts'), contents, 'utf8');
console.log(
  `build info: v${version} ${buildTime} ${commit ?? 'unknown'}${status ? ' (dirty)' : ''}`
);
